(() => {
  'use strict';
  const host = location.hostname.toLowerCase();
  if (!['theboogeymansclub.com', 'www.theboogeymansclub.com', 'boogeymanbeater.com', 'www.boogeymanbeater.com'].includes(host)) return;
  if (window.__boogeyCelebrationLoaded) return;
  window.__boogeyCelebrationLoaded = true;

  const celebration = new Audio('data:audio/mpeg;base64,');
  celebration.preload = 'auto';
  celebration.volume = 0.38;
  const pendingRatings = new Map();
  const pendingComments = new Map();
  const maxWait = 120000;

  function cheer() {
    try {
      celebration.currentTime = 0;
      const playback = celebration.play();
      if (playback && typeof playback.catch === 'function') playback.catch(() => {});
    } catch (_) { /* Browser may block audio; never interfere with the form. */ }
  }

  function countVotes(rating) {
    const summary = rating.querySelector('.jw-element-rating__text--summary');
    if (!summary) return null;
    const digits = summary.textContent.replace(/[^0-9]/g, '');
    return digits ? Number(digits) : null;
  }

  function armRating(rating) {
    if (!rating || !rating.id || !rating.dataset.jwElementId) return;
    const content = rating.querySelector('.jw-element-rating-content');
    if (!content || content.classList.contains('jw-element-rating--voted') || !content.classList.contains('jw-element-rating--voting-enabled')) return;
    const count = countVotes(rating);
    if (!Number.isSafeInteger(count)) return;
    pendingRatings.set(rating.id, {original: rating, count, at: Date.now()});
  }

  document.addEventListener('click', event => {
    if (!event.isTrusted || !event.target || !event.target.closest) return;
    const label = event.target.closest('.jw-rating label.jw-element-rating__star');
    if (label) armRating(label.closest('.jw-rating'));
  }, true);

  document.addEventListener('submit', event => {
    if (!event.isTrusted || !event.target || !event.target.matches) return;
    const form = event.target;
    if (form.matches('.jw-rating form[name="rating"]')) {
      armRating(form.closest('.jw-rating'));
    } else if (form.matches('.jw-comment-module form[name="comment"]')) {
      const parent = form.parentElement;
      if (!parent) return;
      pendingComments.set(form, {parent, previous: new Set(parent.querySelectorAll('.jw-comment-success')), at: Date.now()});
    }
  }, true);

  const observer = new MutationObserver(() => {
    const now = Date.now();
    for (const [form, pending] of pendingComments) {
      if (now - pending.at > maxWait) { pendingComments.delete(form); continue; }
      if (form.isConnected) continue;
      const success = [...pending.parent.querySelectorAll('.jw-comment-success')].find(el => !pending.previous.has(el) && el.textContent.trim());
      if (success) { pendingComments.delete(form); cheer(); }
    }
    for (const [id, pending] of pendingRatings) {
      if (now - pending.at > maxWait) { pendingRatings.delete(id); continue; }
      const replacement = document.getElementById(id);
      if (!replacement || replacement === pending.original || !replacement.classList.contains('jw-rating')) continue;
      pendingRatings.delete(id);
      const count = countVotes(replacement);
      if (replacement.dataset.jwElementId === pending.original.dataset.jwElementId && replacement.querySelector('.jw-element-rating--voted') && Number.isSafeInteger(count) && count > pending.count) cheer();
    }
  });
  observer.observe(document.documentElement, {childList: true, subtree: true});
})();
